const dialog=document.querySelector('#dialog');let pageOpener;function show(title,body,status='SVS GROUP OF INSTITUTIONS'){pageOpener=document.activeElement;document.querySelector('#dialog-content').innerHTML=`<span class="status">${status}</span><h2>${title}</h2>${body}`;dialog.showModal()}document.querySelector('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('close',()=>pageOpener?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});document.querySelector('#menu').onclick=()=>{const open=document.querySelector('#nav').classList.toggle('open');document.querySelector('#menu').setAttribute('aria-expanded',open)};document.querySelectorAll('[data-portal]').forEach(b=>b.onclick=()=>show(b.dataset.portal,'<p>This portal is a presentation demonstration. Authentication, academic records and backend services remain in development.</p><p>No credentials are collected.</p>','DEMONSTRATION · IN DEVELOPMENT'));document.querySelectorAll('[data-policy]').forEach(b=>b.onclick=()=>show(b.dataset.policy==='privacy'?'Privacy notice':'Website disclaimer','<p>This is an institutional presentation preview. Official academic details, contacts and regulatory records require verification. Portal services are demonstrations.</p><p>No data is submitted by the enquiry preview. Website search runs locally. Fonts load from Google Fonts; the dental image is illustrative stock photography. An institution-approved privacy policy is required before live collection of personal information.</p>','DRAFT · INSTITUTIONAL REVIEW REQUIRED'));
